class MoveImportsToTypeCheckingBlockVisitor():
    CONTEXT_KEY = "MoveImportsToTypeCheckingBlockVisitor"

    def __init__(
        self,
        context: CodemodContext,
    ) -> None:
        super().__init__(context)

        self.import_items_to_be_moved: List[ImportItem] = []

    @staticmethod
    def store_imports_in_context(
        context: CodemodContext,
        import_items_to_be_moved: List[ImportItem],
    ) -> None:
        context.scratch[MoveImportsToTypeCheckingBlockVisitor.CONTEXT_KEY] = (
            import_items_to_be_moved,
        )

    @staticmethod
    def _add_type_checking_import(source_module: Module) -> Module:
        context = CodemodContext()
        AddImportsVisitor.add_needed_import(context, "typing", "TYPE_CHECKING")
        transformer = AddImportsVisitor(context)
        transformed_source_module = transformer.transform_module(source_module)
        return transformed_source_module

    def _remove_imports(self, tree: Module) -> Module:
        transformer = RemoveImportsTransformer(self.import_items_to_be_moved)
        transformed_source_module = tree.visit(transformer)
        return transformed_source_module

    def _get_import_module(self) -> Module:
        empty_code = libcst.parse_module("")
        context = CodemodContext()
        context.scratch[AddImportsVisitor.CONTEXT_KEY] = self.import_items_to_be_moved
        transformer = AddImportsVisitor(context)
        transformed_source_module = transformer.transform_module(empty_code)
        return transformed_source_module

    @staticmethod
    def _replace_pass_with_imports(
        placeholder_module: Module, import_module: Module
    ) -> Module:
        return placeholder_module.with_deep_changes(
            old_node=cast(BaseSuite, placeholder_module.body[0].body),
            body=import_module.body,
        )

    def _split_module(self, module: Module) -> Tuple[
        List[Union[SimpleStatementLine, BaseCompoundStatement]],
        List[Union[SimpleStatementLine, BaseCompoundStatement]],
    ]:
        type_checking_block_add_location = 0
        gatherer = GatherImportsVisitor(self.context)
        module.visit(gatherer)
        all_imports = gatherer.all_imports

        for i, statement in enumerate(module.body):
            if isinstance(statement, SimpleStatementLine):
                for possible_import in statement.body:
                    for last_import in all_imports:
                        if possible_import is last_import:
                            type_checking_block_add_location = i + 1
                            break

        return (
            list(module.body[:type_checking_block_add_location]),
            list(module.body[type_checking_block_add_location:]),
        )

    def _add_if_type_checking_block(self, module: Module) -> Module:
        if not self.import_items_to_be_moved:
            return module

        import_module = self._get_import_module()

        placeholder_module = libcst.parse_module("\nif TYPE_CHECKING:\n    pass\n")
        type_checking_block_module = self._replace_pass_with_imports(
            placeholder_module,
            import_module,
        )

        # Find the point of insertion for the TYPE_CHECKING block
        statements_before_imports, statements_after_imports = self._split_module(module)

        updated_body_list = [
            *statements_before_imports,
            type_checking_block_module,
            *statements_after_imports,
        ]

        return module.with_changes(body=updated_body_list)

    @staticmethod
    def _remove_typing_module(import_item_list: List[ImportItem]) -> List[ImportItem]:
        ret: List[ImportItem] = []
        for import_item in import_item_list:
            if import_item.module_name != "typing":
                ret.append(import_item)
        return ret

    def transform_module_impl(
        self,
        tree: Module,
    ) -> Module:
        # Add from typing import TYPE_CHECKING
        tree = self._add_type_checking_import(tree)

        context_contents = self.context.scratch.get(
            MoveImportsToTypeCheckingBlockVisitor.CONTEXT_KEY
        )
        if context_contents is not None:
            (import_items_to_be_moved,) = context_contents

            self.import_items_to_be_moved = import_items_to_be_moved

            # Remove typing library since we do not want it
            # to be imported inside the if TYPE_CHECKING block
            self.import_items_to_be_moved = self._remove_typing_module(
                self.import_items_to_be_moved
            )

            # Remove the newer imports since those are to be
            # shifted inside the if TYPE_CHECKING block
            tree = self._remove_imports(tree)

            # Add the new imports inside if TYPE_CHECKING block
            tree = self._add_if_type_checking_block(tree)

        return tree

class RemoveImportsTransformer():
    def __init__(
        self,
        import_items_to_be_removed: List[ImportItem],
    ) -> None:
        super().__init__()
        self.import_items_to_be_removed = import_items_to_be_removed

    def leave_Import(
        self, original_node: Import, updated_node: Import
    ) -> Union[
        BaseSmallStatement, FlattenSentinel[BaseSmallStatement], RemovalSentinel
    ]:
        names_to_keep = []
        for name in updated_node.names:
            module_name = name.evaluated_name
            found = False
            for import_item in self.import_items_to_be_removed:
                if import_item.module_name == module_name:
                    found = True
                    break
            if not found:
                names_to_keep.append(name.with_changes(comma=MaybeSentinel.DEFAULT))

        if not names_to_keep:
            return RemoveFromParent()
        else:
            return updated_node.with_changes(names=names_to_keep)

    def leave_ImportFrom(
        self, original_node: ImportFrom, updated_node: ImportFrom
    ) -> Union[
        BaseSmallStatement, FlattenSentinel[BaseSmallStatement], RemovalSentinel
    ]:
        if isinstance(updated_node.names, ImportStar):
            return updated_node

        names_to_keep = []
        module_name = get_absolute_module_from_package_for_import(None, updated_node)
        for name in updated_node.names:
            name_value = name.name.value
            found = False
            for import_item in self.import_items_to_be_removed:
                if (
                    import_item.module_name == module_name
                    and import_item.obj_name == name_value
                ):
                    found = True
                    break
            if not found:
                names_to_keep.append(name.with_changes(comma=MaybeSentinel.DEFAULT))

        if not names_to_keep:
            return RemoveFromParent()
        else:
            return updated_node.with_changes(names=names_to_keep)

class RewriteLargeUnion():
    """Rewrite Union[T1, ..., TN] as Any for large N."""

    def __init__(self, max_union_len: int = 5):
        super().__init__()
        self.max_union_len = max_union_len

    def _rewrite_to_tuple(self, union):
        """Union[Tuple[V, ..., V], Tuple[V, ..., V], ...] -> Tuple[V, ...]"""
        value_type = None
        for t in union.__args__:
            if not is_generic_of(t, Tuple):
                return None
            value_type = value_type or t.__args__[0]
            if not all(vt is value_type for vt in t.__args__):
                return None
        return Tuple[value_type, ...]

    def rewrite_Union(self, union):
        if len(union.__args__) <= self.max_union_len:
            return union

        rw_union = self._rewrite_to_tuple(union)
        if rw_union is not None:
            return rw_union

        try:
            for ancestor in inspect.getmro(union.__args__[0]):
                if ancestor is not object and all(
                    issubclass(t, ancestor) for t in union.__args__
                ):
                    return ancestor
        except (TypeError, AttributeError):
            pass
        return Any

class ModuleStub():
    def __init__(
        self,
        function_stubs: Optional[Iterable[FunctionStub]] = None,
        class_stubs: Optional[Iterable[ClassStub]] = None,
        imports_stub: Optional[ImportBlockStub] = None,
        typed_dict_class_stubs: Optional[Iterable[ClassStub]] = None,
    ) -> None:
        self.function_stubs: Dict[str, FunctionStub] = {}
        if function_stubs is not None:
            self.function_stubs = {stub.name: stub for stub in function_stubs}
        self.class_stubs: Dict[str, ClassStub] = {}
        if class_stubs is not None:
            self.class_stubs = {stub.name: stub for stub in class_stubs}
        self.imports_stub = imports_stub if imports_stub else ImportBlockStub()
        self.typed_dict_class_stubs: List[ClassStub] = []
        if typed_dict_class_stubs is not None:
            self.typed_dict_class_stubs = list(typed_dict_class_stubs)

    def render(self) -> str:
        parts = []
        if self.imports_stub.imports:
            parts.append(self.imports_stub.render())
        for typed_dict_class_stub in sorted(
            self.typed_dict_class_stubs, key=lambda s: s.name
        ):
            parts.append(typed_dict_class_stub.render())
        for func_stub in sorted(self.function_stubs.values(), key=lambda s: s.name):
            parts.append(func_stub.render())
        for class_stub in sorted(self.class_stubs.values(), key=lambda s: s.name):
            parts.append(class_stub.render())
        return "\n\n\n".join(parts)

    def __repr__(self) -> str:
        return "ModuleStub(%s, %s, %s, %s)" % (
            tuple(self.function_stubs.values()),
            tuple(self.class_stubs.values()),
            repr(self.imports_stub),
            tuple(self.typed_dict_class_stubs),
        )

class RenderAnnotation():
    """Render annotation recursively."""

    def make_anonymous_typed_dict(
        self, required_fields: Dict[str, str], optional_fields: Dict[str, str]
    ) -> str:
        raise Exception(
            "Should not receive an anonymous TypedDict in RenderAnnotation,"
            f" but was called with required_fields={required_fields}, optional_fields={optional_fields}."
        )

    def make_builtin_typed_dict(
        self, name: str, annotations: Dict[str, str], total: bool
    ) -> str:
        raise Exception(
            "Should not receive a TypedDict type in RenderAnnotation,"
            f" but was called with name={name}, annotations={annotations}, total={total}."
        )

    def generic_rewrite(self, typ: Any) -> str:
        if hasattr(typ, "__supertype__"):
            rendered = str(typ.__name__)
        elif is_forward_ref(typ):
            rendered = repr(typ.__forward_arg__)
        elif isinstance(typ, NoneType) or typ is NoneType:
            rendered = "None"
        elif is_generic(typ):
            rendered = repr(typ)
        elif isinstance(typ, type):
            if typ.__module__ in ("builtins",):
                rendered = typ.__qualname__
            else:
                rendered = typ.__module__ + "." + typ.__qualname__
        elif isinstance(typ, str):
            rendered = typ
        else:
            rendered = repr(typ)
        return rendered

    def rewrite_container_type(self, container_type: Any) -> str:
        return repr(container_type)

    def rewrite_malformed_container(self, container: Any) -> str:
        return repr(container)

    def rewrite_type_variable(self, type_variable: Any) -> str:
        rendered = str(type_variable)
        tilde_prefix = "~"
        return (
            rendered[len(tilde_prefix) :]
            if rendered.startswith(tilde_prefix)
            else rendered
        )

    def make_builtin_tuple(self, elements: Iterable[str]) -> str:
        elems = list(elements)
        return ", ".join(elems) if elems else "()"

    def make_container_type(self, container_type: str, elements: str) -> str:
        return f"{container_type}[{elements}]"

    def rewrite_Union(self, union: type) -> str:
        if _is_optional(union):
            elem_type = _get_optional_elem(union)
            return "Optional[" + self.rewrite(elem_type) + "]"
        return self._rewrite_container(Union, union)

    def rewrite(self, typ: type) -> str:
        rendered = super().rewrite(typ)
        if getattr(typ, "__module__", None) == "typing":
            rendered = rendered.replace("typing.", "")
        # Temporary hacky workaround for #76 to fix remaining NoneType hints by search-replace
        rendered = rendered.replace("NoneType", "None")
        return rendered

class FunctionStub():
    def __init__(
        self,
        name: str,
        signature: inspect.Signature,
        kind: FunctionKind,
        strip_modules: Optional[Iterable[str]] = None,
        is_async: bool = False,
    ) -> None:
        self.name = name
        self.signature = signature
        self.kind = kind
        self.strip_modules = strip_modules or []
        self.is_async = is_async

    def render(self, prefix: str = "") -> str:
        s = prefix
        if self.is_async:
            s += "async "
        s += "def " + self.name
        s += render_signature(self.signature, 120 - len(s), prefix) + ": ..."
        # Yes, this is a horrible hack, but inspect.py gives us no way to
        # specify the function that should be used to format annotations.
        for module in self.strip_modules:
            s = s.replace(module + ".", "")
        if self.kind == FunctionKind.CLASS:
            s = prefix + "@classmethod\n" + s
        elif self.kind == FunctionKind.STATIC:
            s = prefix + "@staticmethod\n" + s
        elif self.kind == FunctionKind.PROPERTY:
            s = prefix + "@property\n" + s
        elif self.kind == FunctionKind.DJANGO_CACHED_PROPERTY:
            s = prefix + "@cached_property\n" + s
        return s

    def __repr__(self) -> str:
        return "FunctionStub(%s, %s, %s, %s, %s)" % (
            repr(self.name),
            repr(self.signature),
            repr(self.kind),
            repr(self.strip_modules),
            self.is_async,
        )

class GenericTypeRewriter(Generic[T], ):
    @abstractmethod
    def make_builtin_tuple(self, elements): ...

    @abstractmethod
    def make_container_type(self, container_type, element): ...

    @abstractmethod
    def make_anonymous_typed_dict(self, required_fields, optional_fields): ...

    @abstractmethod
    def make_builtin_typed_dict(self, name, annotations, total): ...

    @abstractmethod
    def generic_rewrite(self, typ): ...

    @abstractmethod
    def rewrite_container_type(self, container_type): ...

    @abstractmethod
    def rewrite_malformed_container(self, container): ...

    @abstractmethod
    def rewrite_type_variable(self, type_variable): ...

    def _rewrite_container(self, cls, container):
        if container.__module__ != "typing":
            return self.rewrite_malformed_container(container)
        args = getattr(container, "__args__", None)
        if args is None:
            return self.rewrite_malformed_container(container)
        elif args == ((),):  # special case of empty tuple `Tuple[()]`
            elems = self.make_builtin_tuple(())
        else:
            elems = self.make_builtin_tuple(
                self.rewrite(elem) for elem in container.__args__
            )
        return self.make_container_type(self.rewrite_container_type(cls), elems)

    def rewrite_Dict(self, dct):
        return self._rewrite_container(Dict, dct)

    def rewrite_List(self, lst):
        return self._rewrite_container(List, lst)

    def rewrite_Set(self, st):
        return self._rewrite_container(Set, st)

    def rewrite_Tuple(self, tup):
        return self._rewrite_container(Tuple, tup)

    def rewrite_Generator(self, generator):
        return self._rewrite_container(Generator, generator)

    def rewrite_anonymous_TypedDict(self, typed_dict):
        assert is_anonymous_typed_dict(typed_dict)
        required_fields, optional_fields = field_annotations(typed_dict)
        return self.make_anonymous_typed_dict(
            required_fields={
                name: self.rewrite(typ) for name, typ in required_fields.items()
            },
            optional_fields={
                name: self.rewrite(typ) for name, typ in optional_fields.items()
            },
        )

    def rewrite_TypedDict(self, typed_dict):
        if is_anonymous_typed_dict(typed_dict):
            return self.rewrite_anonymous_TypedDict(typed_dict)
        return self.make_builtin_typed_dict(
            typed_dict.__name__,
            {
                name: self.rewrite(typ)
                for name, typ in typed_dict.__annotations__.items()
            },
            total=typed_dict.__total__,
        )

    def rewrite_Union(self, union):
        return self._rewrite_container(Union, union)

    def rewrite(self, typ):
        if is_any(typ):
            typname = "Any"
        elif is_union(typ):
            typname = "Union"
        elif is_typed_dict(typ):
            typname = "TypedDict"
        elif is_generic(typ):
            typname = name_of_generic(typ)
        else:
            typname = getattr(typ, "__name__", None)
        rewriter = getattr(self, "rewrite_" + typname, None) if typname else None
        if rewriter:
            return rewriter(typ)
        if isinstance(typ, TypeVar):
            return self.rewrite_type_variable(typ)
        return self.generic_rewrite(typ)

class ReplaceTypedDictsWithStubs():
    """Replace TypedDicts in a generic type with class stubs and store all the stubs."""

    def __init__(self, class_name_hint: str) -> None:
        self._class_name_hint = class_name_hint
        self.stubs: List[ClassStub] = []

    def _rewrite_container(self, cls: type, container: type) -> type:
        """Rewrite while using the index of the inner type as a class name hint.

        Otherwise, Tuple[TypedDict(...), TypedDict(...)] would give the same
        name for both the generated classes."""
        if container.__module__ != "typing":
            return container
        args = getattr(container, "__args__", None)
        if args is None:
            return container
        elif args == ((),) or args == ():  # special case of empty tuple `Tuple[()]`
            elems: Tuple[Any, ...] = ()
        else:
            # Avoid adding a suffix for the first one so that
            # single-element containers don't have a numeric suffix.
            elems, stub_lists = zip(
                *[
                    self.rewrite_and_get_stubs(
                        elem,
                        class_name_hint=self._class_name_hint
                        + ("" if index == 0 else str(index + 1)),
                    )
                    for index, elem in enumerate(args)
                ]
            )
            for stubs in stub_lists:
                self.stubs.extend(stubs)
        # Value of type "type" is not indexable.
        return cls[elems]  # type: ignore[no-any-return,index]

    def _add_typed_dict_class_stub(
        self,
        fields: Dict[str, type],
        class_name: str,
        base_class_name: str = "TypedDict",
        total: bool = True,
    ) -> None:
        attribute_stubs = []
        for name, typ in fields.items():
            rewritten_type, stubs = self.rewrite_and_get_stubs(
                typ, class_name_hint=name
            )
            attribute_stubs.append(AttributeStub(name, rewritten_type))
            self.stubs.extend(stubs)
        total_flag = "" if total else ", total=False"
        self.stubs.append(
            ClassStub(
                name=f"{class_name}({base_class_name}{total_flag})",
                function_stubs=[],
                attribute_stubs=attribute_stubs,
            )
        )

    def rewrite_anonymous_TypedDict(self, typed_dict: type) -> ForwardRef:  # type: ignore[override]
        class_name = get_typed_dict_class_name(self._class_name_hint)
        required_fields, optional_fields = field_annotations(typed_dict)
        has_required_fields = len(required_fields) != 0
        has_optional_fields = len(optional_fields) != 0
        if not has_required_fields and not has_optional_fields:
            raise Exception(
                "Expected empty TypedDicts to be shrunk as Dict[Any, Any]"
                " but got an empty TypedDict anyway"
            )
        elif has_required_fields and not has_optional_fields:
            self._add_typed_dict_class_stub(required_fields, class_name)
        elif not has_required_fields and has_optional_fields:
            self._add_typed_dict_class_stub(optional_fields, class_name, total=False)
        else:
            self._add_typed_dict_class_stub(required_fields, class_name)
            base_class_name = class_name
            class_name = get_typed_dict_class_name(self._class_name_hint) + "NonTotal"
            self._add_typed_dict_class_stub(
                optional_fields, class_name, base_class_name, total=False
            )
        return make_forward_ref(class_name)

    @staticmethod
    def rewrite_and_get_stubs(
        typ: type, class_name_hint: str
    ) -> Tuple[type, List[ClassStub]]:
        rewriter = ReplaceTypedDictsWithStubs(class_name_hint)
        rewritten_type = rewriter.rewrite(typ)
        return rewritten_type, rewriter.stubs

