        return module.with_changes(body=updated_body_list)

    @staticmethod
    def _remove_typing_module(import_item_list: List[ImportItem]) -> List[ImportItem]:
        ret: List[ImportItem] = []
        for import_item in import_item_list:
            if import_item.module_name != "typing":
                ret.append(import_item)
        return ret

    def transform_module_impl(
        self,
        tree: Module,
    ) -> Module:
        # Add from typing import TYPE_CHECKING
        tree = self._add_type_checking_import(tree)

        context_contents = self.context.scratch.get(
            MoveImportsToTypeCheckingBlockVisitor.CONTEXT_KEY
        )
        if context_contents is not None:
            (import_items_to_be_moved,) = context_contents

            self.import_items_to_be_moved = import_items_to_be_moved

            # Remove typing library since we do not want it
            # to be imported inside the if TYPE_CHECKING block
            self.import_items_to_be_moved = self._remove_typing_module(
                self.import_items_to_be_moved
            )

            # Remove the newer imports since those are to be
            # shifted inside the if TYPE_CHECKING block
            tree = self._remove_imports(tree)

            # Add the new imports inside if TYPE_CHECKING block
            tree = self._add_if_type_checking_block(tree)

        return tree

class RemoveImportsTransformer(CSTTransformer):

    def leave_Import(
        self, original_node: Import, updated_node: Import
    ) -> Union[
        BaseSmallStatement, FlattenSentinel[BaseSmallStatement], RemovalSentinel
    ]:
        names_to_keep = []
        for name in updated_node.names:
            module_name = name.evaluated_name
            found = False
            for import_item in self.import_items_to_be_removed:
                if import_item.module_name == module_name:
                    found = True
                    break
            if not found:
                names_to_keep.append(name.with_changes(comma=MaybeSentinel.DEFAULT))

        if not names_to_keep:
            return RemoveFromParent()
        else:
            return updated_node.with_changes(names=names_to_keep)

    def leave_ImportFrom(
        self, original_node: ImportFrom, updated_node: ImportFrom
    ) -> Union[
        BaseSmallStatement, FlattenSentinel[BaseSmallStatement], RemovalSentinel
    ]:
        if isinstance(updated_node.names, ImportStar):
            return updated_node

        names_to_keep = []
        module_name = get_absolute_module_from_package_for_import(None, updated_node)
        for name in updated_node.names:
            name_value = name.name.value
            found = False
            for import_item in self.import_items_to_be_removed:
                if (
                    import_item.module_name == module_name
                    and import_item.obj_name == name_value
                ):
                    found = True
                    break
            if not found:
                names_to_keep.append(name.with_changes(comma=MaybeSentinel.DEFAULT))

        if not names_to_keep:
            return RemoveFromParent()
        else:
            return updated_node.with_changes(names=names_to_keep)

class Inbox:

    def __init__(self, user: User, repo: RepoInterface) -> None:
        self.user = user
        self.repo = repo
        self.events = self.repo.get_inbox_events_for_user_id(self.user.id)

    def aggregate(self):
        aggregators: List[AggregatorInterface] = [
            CommentsAggregator(self.repo),
            LikesAggregator(self.repo),
            FollowersAggregator(self.repo),
        ]
        aggregators_by_type: Dict[EventType, List[AggregatorInterface]] = {}
        for agg in aggregators:
            aggregators_by_type.setdefault(agg.type, []).append(agg)

        for event in self.events:
            for aggregator in aggregators_by_type.get(event.type, []):
                aggregator.add(event)

        items = chain.from_iterable(
            agg.aggregate() for agg in chain.from_iterable(aggregators_by_type.values())
        )

        return sorted(items, key=attrgetter("published"), reverse=True)

    def _pluralize(self, count):
        return "" if count == 1 else "s"

class RewriteLargeUnion(TypeRewriter):
    """Rewrite Union[T1, ..., TN] as Any for large N."""

    def _rewrite_to_tuple(self, union):
        """Union[Tuple[V, ..., V], Tuple[V, ..., V], ...] -> Tuple[V, ...]"""
        value_type = None
        for t in union.__args__:
            if not is_generic_of(t, Tuple):
                return None
            value_type = value_type or t.__args__[0]
            if not all(vt is value_type for vt in t.__args__):
                return None
        return Tuple[value_type, ...]

    def rewrite_Union(self, union):
        if len(union.__args__) <= self.max_union_len:
            return union

        rw_union = self._rewrite_to_tuple(union)
        if rw_union is not None:
            return rw_union

        try:
            for ancestor in inspect.getmro(union.__args__[0]):
                if ancestor is not object and all(
                    issubclass(t, ancestor) for t in union.__args__
                ):
                    return ancestor
        except (TypeError, AttributeError):
            pass
        return Any

class CallTracer:
    """CallTracer captures the concrete types involved in a function invocation.

    On a per function call basis, CallTracer will record the types of arguments
    supplied, the type of the function's return value (if any), and the types
    of values yielded by the function (if any). It emits a CallTrace object
    that contains the captured types when the function returns.

    Use it like so:

        sys.setprofile(CallTracer(MyCallLogger()))

    """

    def __init__(
        self,
        logger: CallTraceLogger,
        max_typed_dict_size: int,
        code_filter: Optional[CodeFilter] = None,
        sample_rate: Optional[int] = None,
    ) -> None:
        self.logger = logger
        self.traces: Dict[FrameType, CallTrace] = {}
        self.sample_rate = sample_rate
        self.cache: Dict[CodeType, Optional[Callable[..., Any]]] = {}
        self.should_trace = code_filter
        self.max_typed_dict_size = max_typed_dict_size

    def _get_func(self, frame: FrameType) -> Optional[Callable[..., Any]]:
        code = frame.f_code
        if code not in self.cache:
            self.cache[code] = get_func(frame)
        return self.cache[code]

    def handle_call(self, frame: FrameType) -> None:
        if self.sample_rate and random.randrange(self.sample_rate) != 0:
            return
        func = self._get_func(frame)
        if func is None:
            return
        code = frame.f_code
        # I can't figure out a way to access the value sent to a generator via
        # send() from a stack frame.
        if frame in self.traces:
            # resuming a generator; we've already seen this frame
            return
        arg_names = code.co_varnames[: code.co_argcount + code.co_kwonlyargcount]
        arg_types = {}
        for name in arg_names:
            if name in frame.f_locals:
                arg_types[name] = get_type(
                    frame.f_locals[name], max_typed_dict_size=self.max_typed_dict_size
                )
        self.traces[frame] = CallTrace(func, arg_types)

    def __call__(self, frame: FrameType, event: str, arg: Any) -> "CallTracer":
        code = frame.f_code
        if (
            event not in SUPPORTED_EVENTS
            or code.co_name == "trace_types"
            or self.should_trace
            and not self.should_trace(code)
        ):
            return self
        try:
            if event == EVENT_CALL:
                self.handle_call(frame)
            elif event == EVENT_RETURN:
                self.handle_return(frame, arg)
            else:
                logger.error("Cannot handle event %s", event)
        except Exception:
            logger.exception("Failed collecting trace")
        return self

