class Inbox:

    def _pluralize(self, count):
        return "" if count == 1 else "s"

    def summarize(self):
        counter = Counter(e.type for e in self.events)
        clauses: List[str] = []
        likes = counter[EventType.LIKED]
        if likes:
            clauses.append(f"{likes} new like{self._pluralize(likes)}")
        follows = counter[EventType.FOLLOWED]
        if follows:
            clauses.append(f"{follows} new follower{self._pluralize(follows)}")
        comments = counter[EventType.COMMENTED]
        if comments:
            clauses.append(f"{comments} new comment{self._pluralize(comments)}")
        if not clauses:
            combined = "no new activity"
        elif len(clauses) == 1:
            combined = clauses[0]
        else:
            initial = ", ".join(clauses[:-1])
            combined = f"{initial} and {clauses[-1]}"
        return f"You have {combined}."

    def __init__(self, user: User, repo: RepoInterface) -> None:
        self.user = user
        self.repo = repo
        self.events = self.repo.get_inbox_events_for_user_id(self.user.id)

    def aggregate(self):
        aggregators: List[AggregatorInterface] = [
            CommentsAggregator(self.repo),
            LikesAggregator(self.repo),
            FollowersAggregator(self.repo),
        ]
        aggregators_by_type: Dict[EventType, List[AggregatorInterface]] = {}
        for agg in aggregators:
            aggregators_by_type.setdefault(agg.type, []).append(agg)

        for event in self.events:
            for aggregator in aggregators_by_type.get(event.type, []):
                aggregator.add(event)

        items = chain.from_iterable(
            agg.aggregate() for agg in chain.from_iterable(aggregators_by_type.values())
        )

        return sorted(items, key=attrgetter("published"), reverse=True)

class FunctionStub(Stub):

    def render(self, prefix: str = "") -> str:
        s = prefix
        if self.is_async:
            s += "async "
        s += "def " + self.name
        s += render_signature(self.signature, 120 - len(s), prefix) + ": ..."
        # Yes, this is a horrible hack, but inspect.py gives us no way to
        # specify the function that should be used to format annotations.
        for module in self.strip_modules:
            s = s.replace(module + ".", "")
        if self.kind == FunctionKind.CLASS:
            s = prefix + "@classmethod\n" + s
        elif self.kind == FunctionKind.STATIC:
            s = prefix + "@staticmethod\n" + s
        elif self.kind == FunctionKind.PROPERTY:
            s = prefix + "@property\n" + s
        elif self.kind == FunctionKind.DJANGO_CACHED_PROPERTY:
            s = prefix + "@cached_property\n" + s
        return s
    def __init__(
        self,
        name: str,
        signature: inspect.Signature,
        kind: FunctionKind,
        strip_modules: Optional[Iterable[str]] = None,
        is_async: bool = False,
    ) -> None:
        self.name = name
        self.signature = signature
        self.kind = kind
        self.strip_modules = strip_modules or []
        self.is_async = is_async

    def __repr__(self) -> str:
        return "FunctionStub(%s, %s, %s, %s, %s)" % (
            repr(self.name),
            repr(self.signature),
            repr(self.kind),
            repr(self.strip_modules),
            self.is_async,
        )

