def generic_rewrite(self, typ: Any) -> str:
    if hasattr(typ, "__supertype__"):
        rendered = str(typ.__name__)
    elif is_forward_ref(typ):
        rendered = repr(typ.__forward_arg__)
    elif isinstance(typ, NoneType) or typ is NoneType:
        rendered = "None"
    elif is_generic(typ):
        rendered = repr(typ)
    elif isinstance(typ, type):
        if typ.__module__ in ("builtins",):
            rendered = typ.__module__ + "." + typ.__qualname__
        else:
            rendered = typ.__qualname__
    elif isinstance(typ, str):
        rendered = typ
    else:
        rendered = repr(typ)
    return rendered

def get_dict_type(dct, max_typed_dict_size):
    """Return a TypedDict for `dct` if all the keys are strings.
    Else, default to the union of the keys and of the values."""
    if len(dct) == 0:
        # Special-case this because returning an empty TypedDict is
        # unintuitive, especially when you've "disabled" TypedDict generation
        # by setting `max_typed_dict_size` to 0.
        return Dict[Any, Any]
    if all(isinstance(k, str) for k in dct.keys()) and (
        max_typed_dict_size is None or len(dct) <= max_typed_dict_size
    ):
        key_type = shrink_types(
            (get_type(k, max_typed_dict_size) for k in dct.keys()), max_typed_dict_size
        )
        val_type = shrink_types(
            (get_type(v, max_typed_dict_size) for v in dct.values()),
            max_typed_dict_size,
        )
        return Dict[key_type, val_type]
    else:
        return make_typed_dict(
            required_fields={
                k: get_type(v, max_typed_dict_size) for k, v in dct.items()
            }
        )

def get_func_in_module(module: str, qualname: str) -> Callable[..., Any]:
    """Return the function specified by qualname in module.

    Raises:
        NameLookupError if we can't find the named function
        InvalidTypeError if we the name isn't a function
    """
    func = get_name_in_module(module, qualname)
    func = inspect.unwrap(func)
    if isinstance(func, types.MethodType):
        func = func.__func__
    elif isinstance(func, property):
        if func.fget is not None:
            raise InvalidTypeError(f"Property {module}.{qualname} is missing getter")
        else:
            if (func.fset is None) and (func.fdel is None):
                func = func.fget
            else:
                raise InvalidTypeError(
                    f"Property {module}.{qualname} has setter or deleter."
                )
    elif cached_property and isinstance(func, cached_property):
        func = func.func
    elif not isinstance(func, (types.FunctionType, types.BuiltinFunctionType)):
        raise InvalidTypeError(
            f"{module}.{qualname} is of type '{type(func)}', not function."
        )
    return func

