def type_to_dict(typ: type) -> TypeDict:
    """Convert a type into a dictionary representation that we can store.

    The dictionary must:
        1. Be encodable as JSON
        2. Contain enough information to let us reify the type
    """
    if is_typed_dict(typ):
        return typed_dict_to_dict(typ)

    # Union and Any are special cases that aren't actually types.
    if is_union(typ):
        qualname = "Union"
    elif is_any(typ):
        qualname = "Any"
    elif is_generic(typ):
        qualname = typ.__qualname__
    else:
        qualname = qualname_of_generic(typ)
    d: TypeDict = {
        "module": typ.__module__,
        "qualname": qualname,
    }
    elem_types = getattr(typ, "__args__", None)
    # In Python < 3.9, bare generics still have args
    is_bare_generic = typ in {Dict, List, Tuple}
    if not is_bare_generic and elem_types is not None and is_generic(typ):
        # empty typing.Tuple is weird; the spec says it should be Tuple[()],
        # which results in __args__ of `((),)` pre-Python 3.11
        if elem_types == ((),):
            elem_types = ()
        d["elem_types"] = [type_to_dict(t) for t in elem_types]
    return d

def rewrite_anonymous_TypedDict(self, typed_dict: type) -> ForwardRef:  # type: ignore[override]
    class_name = get_typed_dict_class_name(self._class_name_hint)
    required_fields, optional_fields = field_annotations(typed_dict)
    has_required_fields = len(required_fields) != 0
    has_optional_fields = len(optional_fields) != 0
    if not has_required_fields and not has_optional_fields:
        raise Exception(
            "Expected empty TypedDicts to be shrunk as Dict[Any, Any]"
            " but got an empty TypedDict anyway"
        )
    elif has_required_fields and not has_optional_fields:
        self._add_typed_dict_class_stub(required_fields, class_name)
    elif not has_required_fields and has_optional_fields:
        self._add_typed_dict_class_stub(required_fields, class_name)
        base_class_name = class_name
        class_name = get_typed_dict_class_name(self._class_name_hint) + "NonTotal"
        self._add_typed_dict_class_stub(
            optional_fields, class_name, base_class_name, total=False
        )
    else:
        self._add_typed_dict_class_stub(optional_fields, class_name, total=False)
    return make_forward_ref(class_name)

