    return_type: Optional[type],
    yield_type: Optional[type],
    existing_annotation_strategy: ExistingAnnotationStrategy = ExistingAnnotationStrategy.REPLICATE,
) -> "FunctionDefinition":
    typed_dict_class_stubs: List[ClassStub] = []
    new_arg_types = {}
